sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) return;

    var course = g_form.getValue('course');
    var date = g_form.getValue('date');

    if (!course || !date) return;

    var ga = new GlideAjax('CheckScheduleDuplicate');
    ga.addParam('sysparm_name', 'isDuplicate');
    ga.addParam('sysparm_course_id', course);
    ga.addParam('sysparm_date_id', date);

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.clearValue('date');
            g_form.showFieldMsg('date', 'You already have a course scheduled on this date.', 'error');
        } else {
            g_form.hideFieldMsg('date');
		}
    });
}
